?><style>*{box-sizing:border-box}.container{max-width:1200px;margin:30px auto;padding:0 16px}.tool-layout{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:20px;align-items:start}.tool-main,.tool-sidebar{background:#fff;border:1px solid #e5e9f0;border-radius:20px;padding:25px;box-shadow:0 14px 40px rgba(20,30,70,.05)}.tool-sidebar{position:sticky;top:88px;max-height:calc(100vh - 108px);overflow:auto}.tool-sidebar a{display:block;padding:9px 10px;margin:3px 0;border-radius:9px;text-decoration:none;color:#536075;font-size:13px;font-weight:700}.tool-sidebar a:hover,.tool-sidebar a.active{background:#f0efff;color:#635bff}.upload{border:2px dashed #d6dbea;border-radius:15px;padding:42px 20px;text-align:center;cursor:pointer;margin:20px 0}.input{width:100%;padding:12px;border:1px solid #dfe4ec;border-radius:10px;margin:8px 0 14px}.btn{border:0;border-radius:10px;padding:12px 18px;background:#635bff;color:#fff;font-weight:800;cursor:pointer}.result{margin-top:16px;padding:15px;background:#f7f8fb;border:1px solid #e5e9f0;border-radius:12px}@media(max-width:800px){.tool-layout{grid-template-columns:1fr}.tool-sidebar{position:static;max-height:330px}}</style><main class="container"><div class="tool-layout"><section class="tool-main"><h1>PDF Splitter</h1><p>Extract selected pages from a PDF and download them as a new PDF.</p><input id="file" type="file" accept="application/pdf" hidden><div class="upload" id="upload"><strong>📄 Drop PDF here</strong><br>or click to choose a PDF</div><label><strong>Pages</strong> (e.g. 1, 3-5, 8)</label><input class="input" id="pages" placeholder="Leave blank for all pages"><button class="btn" id="split" disabled>Split PDF</button><div class="result" id="result">No PDF selected.</div></section><aside class="tool-sidebar"><h2>🛠️ All Tools</h2><?php $items=['image-compressor.php'=>'🖼️ Image Compressor','png-to-jpg.php'=>'↩️ PNG to JPG','jpg-to-webp.php'=>'🖼️ JPG to WebP','png-to-webp.php'=>'🖼️ PNG to WebP','gif-maker.php'=>'🎞️ GIF Maker','pdf-to-jpg.php'=>'📄 PDF to JPG','pdf-to-png.php'=>'📄 PDF to PNG','pdf-merger.php'=>'📑 PDF Merger','pdf-splitter.php'=>'📄 PDF Splitter','pdf-compressor.php'=>'📦 PDF Compressor','png-to-pdf.php'=>'📄 PNG to PDF','text-to-pdf.php'=>'📝 Text to PDF','qr-generator.php'=>'🔐 QR Code Generator','qr-reader.php'=>'📷 QR Code Reader','age-calculator.php'=>'🎂 Age Calculator','percentage-calculator.php'=>'% Percentage Calculator','bmi-calculator.php'=>'⚖️ BMI Calculator','unit-converter.php'=>'📏 Unit Converter','stopwatch-timer.php'=>'⏱️ Stopwatch Timer','lorem-ipsum-generator.php'=>'📄 Lorem Ipsum','unix-timestamp.php'=>'🕐 Unix Timestamp','timestamp-converter.php'=>'🕐 Timestamp Converter','uuid-generator.php'=>'🆔 UUID Generator','random-number-generator.php'=>'🎲 Random Number Generator','json-formatter.php'=>'{} JSON Formatter','word-counter.php'=>'📝 Word Counter','case-converter.php'=>'🔤 Case Converter','url-encoder.php'=>'🔗 URL Encoder'];foreach($items as $f=>$n):?><a class="<?=basename($_SERVER['SCRIPT_NAME'])===$f?'active':''?>" href="/smart-toolz/tools/<?=htmlspecialchars($f,ENT_QUOTES,'UTF-8')?>"><?=htmlspecialchars($n)?></a><?php endforeach;?><a href="/smart-toolz/tool.php">View All Tools →</a></aside></div></main><script src="https://cdnjs.cloudflare.com/ajax/libs/pdf-lib/1.17.1/pdf-lib.min.js"></script><script>const file=document.getElementById('file'),upload=document.getElementById('upload'),split=document.getElementById('split'),result=document.getElementById('result');upload.onclick=()=>file.click();file.onchange=()=>{const f=file.files[0];split.disabled=!f;result.textContent=f?f.name+' selected.':'No PDF selected.'};function parsePages(s,total){if(!s.trim())return Array.from({length:total},(_,i)=>i);const set=new Set;for(const part of s.split(',')){const p=part.trim();if(/^\d+$/.test(p)){const n=+p;if(n>=1&&n<=total)set.add(n-1)}else if(/^(\d+)\s*-\s*(\d+)$/.test(p)){const[,a,b]=p.match(/^(\d+)\s*-\s*(\d+)$/).map(Number);for(let n=Math.min(a,b);n<=Math.max(a,b)&&n<=total;n++)if(n>=1)set.add(n-1)}}return [...set].sort((a,b)=>a-b)}split.onclick=async()=>{const f=file.files[0];if(!f)return;split.disabled=true;result.textContent='Creating split PDF…';try{const{PDFDocument}=PDFLib,src=await PDFDocument.load(await f.arrayBuffer()),out=await PDFDocument.create(),pages=parsePages(document.getElementById('pages').value,src.getPageCount());if(!pages.length)throw Error('No valid pages');const copied=await out.copyPages(src,pages);copied.forEach(p=>out.addPage(p));const bytes=await out.save(),blob=new Blob([bytes],{type:'application/pdf'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=f.name.replace(/\.pdf$/i,'')+'-split.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);result.textContent=pages.length+' page(s) exported.'}catch(e){console.error(e);result.textContent='Could not split this PDF. Check the page numbers.'}finally{split.disabled=false}}</script><?php require_once __DIR__ . '/../footer.php'; ?>